INSERT INTO domande (materia_id, testo, risposta_a, risposta_b, risposta_c, risposta_corretta) VALUES
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Il contratto di assicurazione, avente ad oggetto il pagamento del prezzo del riscatto in caso di sequestro di persona, è:', 'nullo, salvo il caso in cui il sequestrato sia un minore', 'valido ed efficace', 'nullo', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In base al Regolamento IVASS n. 41/2018, che cosa si intende per prodotti assicurativi vita con “capitale protetto”?', 'Contratti per i quali l’impresa presta una specifica garanzia di conservazione del capitale.', 'Contratti per i quali l’impresa garantisce la corresponsione di un rendimento minimo', 'Contratti per i quali l’impresa adotta particolari tecniche di gestione che mirano a minimizzare la possibilità di perdita del capitale investito', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Nell''assicurazione contro i danni, l''assicuratore risponde del danno cagionato da un vizio intrinseco della cosa assicurata che non gli sia stato denunciato?', 'Sì, sempre', 'Sì, salvo patto contrario', 'No, salvo patto contrario', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'L’assicurato deve dare avviso del sinistro all’assicuratore entro:', '10 giorni da quello in cui il sinistro si è verificato o l’assicurato ne ha avuto conoscenza', '15 giorni da quello in cui il sinistro si è verificato o l’assicurato ne ha avuto conoscenza', '3 giorni da quello in cui il sinistro si è verificato o l’assicurato ne ha avuto conoscenza', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Le spese di salvataggio sostenute dall''assicurato:', 'sono sempre interamente a carico dell''assicuratore', 'sono sempre interamente a carico dell''assicurato', 'sono a carico dell''assicuratore  in proporzione del valore assicurato rispetto a quello che aveva la cosa al tempo del sinistro', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi dell''art. 174, comma 1, del Codice delle assicurazioni private, il contraente di un contratto di assicurazione di "tutela legale" ha facoltà, ove ne abbia la necessità per un procedimento giudiziario o amministrativo, di scegliere un professionista abilitato per la sua difesa?', 'No', 'Sì, ma solo per controversie riguardanti la circolazione stradale', 'Sì', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Il rischio Tutela Legale di cui al ramo 17 può essere garantito dall''impresa di assicurazione in via accessoria, senza necessità di una specifica autorizzazione?', 'Sì, sempre', 'No, mai', 'Sì, ma solo nel caso in cui si tratti di rischi accessori del ramo 18 quando il rischio principale riguardi solo l''assistenza da fornire alle persone in difficoltà durante trasferimenti o assenze dal domicilio o dal luogo di residenza o quando riguardino controversie relative all''utilizzazione di navi o comunque connesse a tale utilizzazione', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'L''impresa di assicurazione deve tenere un registro da cui risultano le attività a copertura delle riserve tecniche dei rami vita e dei rami danni. In qualsiasi momento l''importo degli attivi iscritti, tenendo conto delle annotazioni dei movimenti, deve essere almeno pari:', 'all''80% dell''ammontare delle riserve tecniche', 'al 90% dell''ammontare delle riserve tecniche', 'all''ammontare delle riserve tecniche.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Nei contratti unit linked le imprese comunicano al contraente la riduzione del controvalore delle quote complessivamente detenute dallo stesso, che sia stata accertata in corso di contratto, quando tale riduzione sia:', 'pari al 20% rispetto all’ammontare complessivo dei premi investiti', 'di oltre il 10% rispetto all’ammontare complessivo dei premi investiti', 'di oltre il 30% rispetto all’ammontare del premio, o di una sua parte, che finanzia tale prestazione, tenuto conto di eventuali riscatti.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Qualora l''obbligo di assicurazione della responsabilità civile derivante dalla circolazione dei veicoli a motore sia adempiuto mediante la stipulazione di un contratto in coassicurazione:', 'sul certificato di assicurazione è indicata la denominazione sociale della delegataria se le imprese coassicuratrici rispondono ciascuna in proporzione della rispettiva quota', 'sul certificato di assicurazione sono indicate le denominazioni sociali di tutte le imprese coassicuratrici, se le stesse si sono obbligate in solido  ed è stata individuata una coassicuratrice delegataria', 'sul certificato di assicurazione è indicata la denominazione sociale della sola impresa individuata come delegataria se le imprese coassicuratrici si sono obbligate in solido', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Gli agenti di assicurazione che esercitano l''attività di intermediazione assicurativa tramite tecniche di comunicazione a distanza sono tenuti all''adempimento degli obblighi di informazione precontrattuale?', 'No, mai', 'Sì, salvo che non siano stati espressamente esentati dall''impresa preponente', 'Sì, sempre', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Una SIM può essere iscritta nella sezione B del RUI?', 'Si, sempre', 'Sì, a condizione che distribuisca solo prodotti standardizzati', 'No, mai', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Per operare in Italia in regime di stabilimento, un’impresa avente sede legale in un Paese terzo rispetto all’Unione Europea deve:', 'limitarsi a comunicare preventivamente all’IVASS la sua intenzione di operare in Italia', 'limitarsi a richiedere alla propria Autorità di vigilanza l’autorizzazione ad operare in Italia', 'essere preventivamente autorizzata dall’IVASS', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi del codice delle assicurazioni, a quale compagnia è presentata la richiesta di risarcimento del danno subito dal terzo trasportato nell''assicurazione obbligatoria rc auto?', 'Esclusivamente all’impresa presso la quale è assicurato il responsabile del sinistro', 'All’impresa presso la quale è assicurato il trasportato medesimo', 'All’impresa presso la quale è assicurato il veicolo a bordo del quale il danneggiato si trovava al momento del sinistro, salvo il caso fortuito', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In caso di trasferimento di portafoglio di impresa di assicurazione italiana a favore di un''impresa di assicurazione con sede legale all''estero:', 'i contraenti con domicilio o, se persone giuridiche, sede legale in Italia, possono recedere dal contratto di assicurazione entro 90 giorni dalla pubblicazione del provvedimento di autorizzazione', 'i contraenti con domicilio o, se persone giuridiche, sede legale in Italia, non possono recedere dal contratto di assicurazione', 'i contraenti con domicilio o, se persone giuridiche, sede legale in Italia, possono recedere dal contratto di assicurazione entro 60 giorni dalla pubblicazione del provvedimento di autorizzazione', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In caso di sinistri causati da guida in stato di ebbrezza, l’impresa assicuratrice può esercitare diritto di rivalsa nei confronti del proprio assicurato responsabile per le somme versate al danneggiato?', 'Sì, ma solo per sinistri superiori ad € 100.000', 'No, mai', 'Sì, salvo che il contratto preveda la clausola di rinuncia alla rivalsa', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'L’azione diretta che spetta al danneggiato nei confronti dell’impresa di assicurazione per un sinistro r.c. auto:', 'è soggetta al termine di prescrizione decennale', 'è  soggetta al termine di prescrizione annuale', 'è soggetta al termine di prescrizione cui sarebbe soggetta l’azione verso il responsabile', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Sono considerati provvisoriamente, nei casi indicati dalla normativa, equipollenti al certificato di assicurazione e al contrassegno:', 'la quietanza di pagamento del premio o della rata di premio rilasciata dall’impresa di assicurazione, solo se trasmessa mediante raccomandata', 'l''autocertificazione del contraente attestante l’assolvimento dell’obbligo di assicurazione', 'la quietanza di pagamento del premio o della rata di premio rilasciata dall’impresa di assicurazione, anche se trasmessa mediante telefax o per via telematica', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Nelle imprese di assicurazione, la nomina del titolare della funzione antiriciclaggio:', 'è di competenza dell''assemblea ordinaria', 'è di competenza del collegio sindacale', 'è di competenza dell''organo amministrativo', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'L''assicurazione obbligatoria per i veicoli a motore copre i danni subiti dai pedoni in conseguenza di un incidente nel quale sia stato coinvolto un veicolo?', 'Si, ma solo se è espressamente prevista dalle condizioni generali di contratto', 'No, mai', 'Si, nei limiti in cui sussiste la responsabilità civile del conducente', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Quale, tra le seguenti finalità, non rientra tra quelle poste alla base dell''attività di vigilanza dell''IVASS ai sensi del Codice delle assicurazioni private?', 'La trasparenza e correttezza del comportamento delle imprese di assicurazione', 'La sana e prudente gestione delle imprese di assicurazione e di riassicurazione', 'La tutela della stabilità dei mercati finanziari', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi del Codice delle Assicurazioni private, l''oggetto sociale delle imprese di assicurazione di nuova costituzione deve essere limitato all''esercizio dei soli rami vita oppure dei soli rami danni?', 'Sì, sempre', 'No, mai', 'Sì, con l''eccezione dell''esercizio congiunto dei rami vita e dei soli rami danni infortuni e malattia', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'L''Autorità europea delle assicurazioni e delle pensioni aziendali e professionali è chiamata', 'ESMA', 'EBA', 'EIOPA', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Gli intermediari di cui alla sezione D possono distribuire prodotti non standardizzati a condizione che la distribuzione sia:', 'effettuata esclusivamente dalla direzione centrale e le persone fisiche che distribuiscono i contratti siano iscritte nella sezione B del registro', 'stata preventivamente autorizzata dall''IVASS', 'effettuata esclusivamente all’interno dei locali di tali intermediari e le persone fisiche che distribuiscono i contratti siano iscritte nella sezione A o nella sezione B del registro', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Nei procedimenti amministrativi per l''irrogazione delle sanzioni amministrative, entro quale termine dalla notifica dell''atto di contestazione i soggetti destinatari possono presentare all''IVASS memorie difensive?', '30 giorni', '180 giorni', '60 giorni', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In caso di assegnazione di portafoglio ad un nuovo intermediario, le imprese di assicurazione devono fornire apposita informativa ai contraenti:', 'entro il termine di dieci giorni dalla data di efficacia dell''assegnazione, mediante pubblicazione nella home page del sito internet dell''IVASS.', 'entro il termine di un mese dalla data di efficacia dell''assegnazione, indicando i riferimenti della nuova sede (indirizzo e recapito telefonico), nonché le generalità del nuovo intermediario.', 'entro il termine di dieci giorni dalla data di efficacia dell''assegnazione, indicando i riferimenti della nuova sede (indirizzo e recapito telefonico), nonché le generalità del nuovo intermediario.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'I soggetti che svolgono l''attività di intermediazione assicurativa esclusivamente all’interno dei locali di un agente assicurativo:', 'non devono possedere specifici requisiti di onorabilità e professionalità', 'devono essere iscritti nel RUI', 'devono possedere specifici requisiti di onorabilità e professionalità', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Il regolamento ISVAP n. 23/2008 concernente la disciplina della trasparenza dei premi e delle condizioni di contratto nell’assicurazione obbligatoria per i veicoli a motore e natanti si applica:', 'soltanto alle imprese di assicurazione autorizzate in Italia', 'alle imprese di assicurazione aventi sede legale in uno Stato terzo', 'alle  imprese di assicurazione autorizzate in Italia  nonchè alle imprese di assicurazione aventi sede legale in un altro Stato membro dello Spazio Economico Europeo abilitate in Italia in regime di stabilimento o di libera prestazione di servizi', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi del codice civile, la polizza di assicurazione rilasciata con dicitura "all''ordine":', 'È trasferibile con gli stessi effetti del trasferimento dei titoli di credito all''ordine', 'Non è trasferibile', 'È trasferibile con gli effetti della cessione ordinaria dei crediti', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi dell''art. 1898 c.c., in caso di aggravamento del rischio, tale che se il nuovo stato di cose fosse esistito e fosse stato conosciuto dall''assicuratore al momento della conclusione del contratto questi non avrebbe consentito l''assicurazione, l''assicuratore può recedere dal contratto entro:', '15 giorni dal giorno in cui ha ricevuto la comunicazione o è venuto altrimenti a conoscenza dell''aggravamento del rischio', '45 giorni  dal giorno in cui ha ricevuto la comunicazione o è venuto altrimenti a conoscenza dell''aggravamento del rischio', 'un mese dal giorno in cui ha ricevuto la comunicazione del contraente o è venuto altrimenti a conoscenza dell''aggravamento del rischio', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi dell''art. 1900, l''assicuratore non è obbligato per i sinistri causati con dolo:', 'dei dipendenti dell''assicurato', 'del proprio agente', 'dell''assicurato', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Nell''assicurazione contro i danni, ove si sia verificato un sinistro, ai fini del risarcimento del danno:', 'non può attribuirsi alle cose perite o danneggiate un valore superiore al valore che le stesse avevano al tempo della stipulazione del contratto', 'non può attribuirsi alle cose perite o danneggiate un valore superiore al valore dei premi pagati dall''assicurato durante il rapporto', 'non può attribuirsi alle cose perite o danneggiate un valore superiore al valore che le stesse avevano al tempo del sinistro', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Nell''assicurazione contro i danni, in mancanza di diversa pattuizione al riguardo, l''assicuratore è tenuto a risarcire:', 'solo il danno che poteva prevedersi al momento in cui è sorta l''obbligazione', 'sia il danno sofferto sia il profitto sperato', 'L''assicuratore è tenuto a risarcire, nei modi e nei limiti stabiliti dal contratto, il danno sofferto dall''assicurato', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi del codice civile, l''assicurazione sulla vita a favore di un terzo:', 'non è valida', 'è valida a condizione che il terzo beneficiario sia coniuge o figlio del contraente', 'è valida', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi del Codice delle Assicurazioni private, l''oggetto sociale delle imprese di assicurazione di nuova costituzione deve essere limitato alternativamente all''esercizio dei soli rami vita oppure dei soli rami danni?', 'Sì, senza eccezioni', 'No, senza eccezioni', 'Sì, con l''eccezione dell''esercizio congiunto dei rami vita e dei soli rami danni infortuni e malattia', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In caso di polizza all''ordine o al portatore, l''assicuratore che adempie la prestazione nei confronti del giratario o del portatore anche se questi non è l''assicurato:', 'non è mai liberato', 'è sempre liberato', 'è liberato solo se l''adempimento è eseguito senza dolo o colpa grave', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Il cambiamento di professione dell''assicurato comporta la cessazione degli effetti del contratto di assicurazione sulla vita per il caso di morte:', 'in nessun caso, anche se ha determinato un aggravamento del rischio tale che, se la nuova situazione fosse esistita al tempo del contratto, l''assicuratore non avrebbe consentito l''assicurazione', 'in ogni caso', 'solo se ha determinato un aggravamento del rischio tale che, se la nuova situazione fosse esistita al tempo del contratto, l''assicuratore non avrebbe consentito l''assicurazione', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'L''obbligo a contrarre per i veicoli a motore ed i natanti:', 'Consente alle imprese di rifiutare le proposte relative a veicoli coinvolti in più di cinque sinistri nell''ultimo anno', 'Consente alle imprese di rifiutare le proposte relative a veicoli coinvolti in più di tre sinistri nell''ultimo anno', 'Impegna le imprese ad accettare senza condizione ogni proposta conforme alle condizioni di polizza e alle tariffe preventivamente stabilite', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'L''esercizio in regime di libertà di prestazione di servizi dell''attività di assicurazione da parte di imprese con sede legale in uno stato terzo:', 'è vietato con l''eccezione di sedi secondarie situate in stati terzi di imprese con sede in stati membri', 'è consentito se si tratta di situazioni occasionali', 'è vietato', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi del Codice delle assicurazioni private, l''attività assicurativa privata è esercitabile da:', 's.r.l., mutue e s.p.a.', 'cooperative, s.r.l. e s.p.a.', 'cooperative, mutue assicurative e s.p.a.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Nell''intermediazione delle polizze r.c. auto l''intermediario mette a disposizione del pubblico l''informativa sui livelli provvigionali percepiti:', 'mediante la sola evidenziazione nell''ambito del sito internet eventualmente allestito dall''intermediario medesimo', 'mediante la sola affissione presso i locali dell''intermediario', 'sia tramite l''affissione presso i locali dell''intermediario, sia mediante l''evidenziazione nell''ambito del sito internet o del profilo di social network eventualmente allestito dall''intermediario medesimo', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Il servizio di preventivazione relativo all''assicurazione obbligatoria della responsabilità civile derivante dalla circolazione dei veicoli a motore:', 'è sempre oneroso', 'può essere gratuito o oneroso', 'è sempre gratuito', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'A norma del Regolamento IVASS n. 41/2018, le Condizioni contrattuali relative ai prodotti assicurativi vita diversi dai prodotti di investimento assicurativi devono contenere anche il Glossario?', 'No, è facoltativo.', 'Esclusivamente qualora le Condizioni siano redatte in lingua diversa dall''italiano.', 'Si, sempre.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Nella promozione e nel collocamento di contratti di assicurazione a distanza è consentito l’utilizzo di procedure che impediscono a determinate categorie di contraenti di contattare il distributore?', 'Si, sempre.', 'Si, previa autorizzazione dell’IVASS.', 'No, mai.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi del Regolamento IVASS N. 40/2018, è consentito ai distributori di collocare contratti di assicurazione mediante tecniche di comunicazione a distanza, senza il preventivo consenso espresso del contraente o dell’aderente?', 'Si, solo in caso di assenza di risposta entro un certo termine dalla proposta.', 'Si, sempre.', 'No.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Quale tra le seguenti forme giuridiche NON può essere adottata da un''impresa di assicurazione italiana?', 'Società di mutua assicurazione le cui quote di partecipazione siano rappresentate da azioni', 'Società per azioni', 'Società a responsabilità limitata', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Nei procedimenti amministrativi per l''irrogazione delle sanzioni amministrative pecuniarie, entro quale termine dalla notifica dell''atto di contestazione i soggetti  destinatari possono  presentare all''IVASS scritti difensivi ed altri documenti in ordine ai fatti addebitati?', '30 giorni', '180 giorni', '60 giorni', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Quali tipologie di assicurazioni sono classificate nelle assicurazioni vita-ramo V?', 'Le operazioni di gestione di fondi collettivi costituiti per l''erogazione di prestazioni in caso di morte, in caso di vita o in caso di cessazione o riduzione dell''attività lavorativa', 'Le assicurazioni sulla durata della vita umana', 'Le operazioni di capitalizzazione', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In base al codice civile, se il contraente stipula l''assicurazione in nome altrui senza averne il potere:', 'l''interessato può ratificare il contratto, entro un mese dalla scadenza', 'l''interessato può ratificare il contratto solo se il sinistro non si è ancora verificato', 'l''interessato può ratificare il contratto anche dopo la scadenza o il verificarsi del sinistro', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi dell''art. 1918 del codice civile, in caso di alienazione delle cose assicurate, i diritti e gli obblighi dell''assicurato passano all''acquirente se questi, avuta notizia dell''esistenza del contratto di assicurazione, non dichiara, tramite raccomandata, all''assicuratore, che non intende subentrare nel contratto entro:', 'trenta giorni dalla scadenza del primo premio successivo all''alienazione', 'sessanta giorni dalla scadenza del primo premio successivo all''alienazione', 'dieci giorni dalla scadenza del primo premio successivo all''alienazione', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi dell''art. 308 del D.Lgs. n. 209/2005, come è punito l''abuso di denominazione assicurativa?', 'È punito penalmente.', 'Non è punito.', 'È punito con una sanzione amministrativa pecuniaria.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Un''impresa di assicurazione italiana può avere come oggetto esclusivo l''esercizio all''estero dell''attività assicurativa?', 'Sì, purché l''attività sia svolta in Paesi membri dell''Unione europea', 'Sì, purché l''attività sia svolta in Paesi extracomunitari', 'No, ne è espressamente vietata la costituzione', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Nelle assicurazioni sulla vita-ramo III, in base al Codice delle assicurazioni private, sono comprese:', 'le operazioni di gestione di fondi collettivi costituiti per l''erogazione di prestazioni in caso di morte, in caso di vita o in caso di cessazione o riduzione dell''attività lavorativa', 'le operazioni di capitalizzazione', 'le assicurazioni, di cui ai rami I e II, le cui prestazioni principali sono direttamente collegate al valore di quote di organismi di investimento collettivo del risparmio o di fondi interni ovvero a indici o ad altri valori di riferimento', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'L’impresa, per i prodotti assicurativi vita diversi dai prodotti d’investimento assicurativi e per i prodotti d’investimento assicurativi, comunica al contraente e all’aderente le eventuali variazioni delle informazioni contenute nelle condizioni di assicurazione per effetto di modifiche alla normativa successive alla conclusione del contratto;', 'entro 10 giorni dalla loro entrata in vigore', 'immediatamente', 'in occasione della prima comunicazione da trasmettere in adempimento agli obblighi di informativa previsti dalla normativa vigente.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In una polizza vita di ramo I, l''impresa invia al contraente una comunicazione scritta con l’indicazione del termine di scadenza e della documentazione da trasmettere per la liquidazione della prestazione:', 'almeno sessanta giorni prima della scadenza del contratto', 'almeno novanta giorni prima della scadenza del contratto', 'almeno trenta giorni prima della scadenza del contratto', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In base all''art. 1887 del codice civile, la proposta scritta diretta all''assicuratore:', 'è revocabile in ogni momento', 'resta ferma per il termine di un anno', 'Resta ferma per il termine di 15 giorni o di 30 giorni quando occorre una visita medica', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi dell''art. 1895 del codice civile, se il rischio non è mai esistito o ha cessato di esistere prima della conclusione del contratto:', 'il contratto è annullabile', 'il contratto è rescindibile', 'il contratto è nullo', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'L''assicurazione sulla vita può essere stipulata:', 'Solo sulla vita propria', 'Solo sulla vita di un terzo', 'Sulla vita propria o di un terzo', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Applicando la regola proporzionale in caso di assicurazione parziale, l''indennizzo è pari:', 'all''ammontare del danno moltiplicato per il rapporto tra il valore effettivo della cosa al tempo del sinistro ed il valore assicurato', 'al valore effettivo della cosa al tempo del sinistro meno il valore assicurato', 'all''ammontare del danno  moltiplicato per il rapporto tra il valore assicurato e il valore effettivo della cosa al tempo del sinistro', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Nelle polizze index linked, per «rischio di performance» si intende:', 'Il rischio che gli attivi destinati a copertura delle riserve tecniche non consentano di replicare l''andamento del valore dell''indice azionario o del diverso valore di riferimento.', 'Il rischio che l''ente emittente o la controparte non adempia ai propri obblighi contrattuali.', 'Il rischio che il valore degli attivi destinati a copertura delle riserve tecniche non sia tale da consentire la conservazione o la rivalutazione del capitale fino all''ammontare minimo garantito.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi del Regolamento ISVAP n. 23/2008, nell''assicurazione r.c. auto il preventivo gratuito personalizzato presso i punti vendita indica, tra l''altro:', 'La misura della provvigione riconosciuta dall’impresa all’intermediario secondo procedure prestabilite dall''IVASS.', 'Nessun tipo di provvigioni.', 'La misura della provvigione riconosciuta dall’impresa all’intermediario in base alla tipologia del contratto e alla categoria dei veicoli.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Il contratto di assicurazione è un contratto:', 'reale.', 'a effetti reali', 'consensuale.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi del Regolamento ISVAP n. 32/2009, gli indici sull''inflazione relativi ai contratti index linked sono calcolati:', 'Annualmente dall''impresa di assicurazione.', 'Semestralmente dall''IVASS.', 'Periodicamente da enti o organismi statistici pubblici, nazionali e sovranazionali.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Trattandosi di assicurazione sulla vita di un terzo, in quali casi questa può essere stipulata?', 'Solo se il terzo vi abbia interesse.', 'In ogni caso, anche senza il consenso del terzo.', 'Solo in presenza di un consenso scritto del terzo.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Un''impresa comunitaria per poter esercitare in Italia in regime di libera prestazione di servizi l''assicurazione obbligatoria di responsabilità civile derivante dalla circolazione dei veicoli a motore e dei natanti deve:', 'Nominare un perito in Italia per la gestione dei sinistri e per la liquidazione dei relativi risarcimenti.', 'Designare un arbitro per la risoluzione delle possibili controversie e per la liquidazione dei relativi risarcimenti.', 'Nominare un rappresentante incaricato della gestione dei sinistri e della liquidazione dei relativi risarcimenti.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In caso di sinistro rcauto, chi è tenuto a risarcire il danno del terzo trasportato?', 'Il terzo trasportato non ha diritto ad alcun risarcimento, potendo solo limitarsi a citare in giudizio l''impresa che assicura il veicolo che ha causato il danno.', 'L''impresa di assicurazione che assicura il veicolo che ha cagionato il danno.', 'L''impresa di assicurazione del veicolo sul quale era a bordo al momento del sinistro, a prescindere dall''accertamento della responsabilità dei conducenti dei veicoli coinvolti nel sinistro.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Trattandosi di r.c. auto, all''UCI (Ufficio Centrale Italiano) è attribuita la competenza a risarcire i danni causati sul territorio italiano:', 'Da veicoli con targa italiana.', 'Da veicoli privi di copertura assicurativa.', 'Da veicoli con targa estera.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Trattandosi di r.c. auto, se l''ammontare del danno derivante da un sinistro stradale supera il massimale previsto dalla polizza che assicura il veicolo:', 'Per la parte eccedente interviene il Fondo di Garanzia per le vittime della strada.', 'La parte eccedente resta a carico del danneggiato.', 'La parte eccedente è a carico del responsabile del sinistro.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'I soggetti che non svolgono attività assicurativa, riassicurativa, attività di intermediazione assicurativa e riassicurativa sono legittimati ad utilizzare, nella denominazione/ ragione sociale e nelle altre comunicazioni al pubblico, le parole «assicurazione», «assicurativa» o similari?', 'Sì, ma solo se hanno ricevuto autorizzazione dell''IVASS almeno 30 gg prima dell''uso della denominazione o ragione sociale in cui compare la parola «assicurazione», «assicurativa» o similari', 'No, anche se le stesse sono coerenti con l''oggetto sociale e siano accompagnate da espressioni idonee ad escludere ogni possibilità di equivoco o di ingannevolezza', 'Si, a condizione che le stesse siano coerenti con l''oggetto sociale e siano accompagnate da espressioni idonee ad escludere ogni possibilità di equivoco o di ingannevolezza circa la natura delle attività esercitate.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Quali soggetti che operano nel settore assicurativo sono tenuti a dotarsi di un indirizzo di posta elettronica certificata?', 'Solo gli intermediari iscritti nella sezione D del registro.', 'Solo gli intermediari iscritti nelle sezioni A e B del registro.', 'Le imprese italiane e gli intermediari iscritti nelle sezioni A, B, D e F del registro.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Le imprese e gli intermediari sono tenuti a prevedere l’uso di strumenti di pagamento elettronici per corrispondere i premi assicurativi?', 'Si, è in loro facoltà prevedere l’uso di tali strumenti, con le modalità e gli oneri a carico del cliente da essi stessi stabiliti.', 'No, sono tenuti a prevedere l''uso di strumenti elettronici solo per lo scambio di comunicazioni e corrispondenza.', 'Si, senza oneri a carico dei clienti, anche nella forma on line.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Che cosa si intende per fatto accidentale nelle assicurazioni per responsabilità civile?', 'L''evento causato da colpa.', 'L''evento dovuto a dolo o colpa grave.', 'L''evento che esula dalle normali previsioni.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Gli intermediari iscritti nella sezione B del RUI sono tenuti ad adottare una politica di gestione dei reclami di propria pertinenza, inclusi quelli relativi ai comportamenti dei dipendenti e dei collaboratori?', 'Si, ove ricorrano determinate condizioni.', 'Si, sempre.', 'No.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi dell''art. 1896 del codice civile, se il rischio cessa di esistere dopo la stipulazione del contratto:', 'il contratto di assicurazione si scioglie e l''assicuratore non ha diritto al pagamento del premio', 'il contratto di assicurazione non si scioglie e l''assicuratore ha diritto al pagamento integrale dei premi', 'il contratto di assicurazione si scioglie, ma l''assicuratore ha diritto al pagamento dei premi finché la cessazione del rischio non gli sia comunicata o non venga altrimenti a sua conoscenza', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi del Codice delle assicurazioni private, il prezzo del riscatto in caso di sequestro di persona, può formare oggetto di un contratto di assicurazione?', 'Sì, sempre', 'Sì, ma solo nei casi espressamente previsti dalla legge.', 'No, mai', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In base al Codice delle assicurazioni private, il rischio "Infortuni" del ramo danni:', 'non comprende gli infortuni sul lavoro', 'non comprende le malattie professionali', 'comprende gli infortuni sul lavoro e le malattie professionali', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'I poteri esercitati dall''IVASS nell''ambito dei propri compiti di vigilanza sul settore assicurativo, sono di natura:', 'Solo accertativa.', 'Solo prescrittiva.', 'Autorizzativa, prescrittiva, accertativa, cautelare e repressiva.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'L''autorizzazione rilasciata dall''IVASS alle imprese di assicurazioni aventi sede legale in Italia, è valida:', 'per il solo territorio della Repubblica.', 'solo per il territorio della Repubblica e per quello degli altri Stati membri dell''Unione europea, nel rispetto delle disposizioni relative alle condizioni di accesso in regime di stabilimento o di prestazione di servizi.', 'per il territorio della Repubblica e per quello degli altri Stati membri dell''Unione europea, nel rispetto delle disposizioni relative alle condizioni di accesso in regime di stabilimento o di prestazione di servizi, nonché per quello degli Stati terzi, nel rispetto della legislazione di tali Stati.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Quali tipologie di assicurazioni sono classificate nelle assicurazioni vita-ramo VI?', 'Le operazioni di capitalizzazione.', 'Le assicurazioni sulla durata della vita umana.', 'Le operazioni di gestione di fondi collettivi costituiti per l''erogazione di prestazioni in caso di morte, in caso di vita o in caso di cessazione o riduzione dell''attività lavorativa.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Tizio ha contratto un''assicurazione sulla vita che designa Caio come beneficiario. Dopo la morte di Tizio, il beneficio può essere revocato?', 'Sì, anche dagli eredi di Tizio', 'Sì, solo dagli eredi di Tizio', 'No, il beneficio non può essere revocato', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi dell''art. 1888 del Codice Civile, nel contratto di assicurazione, che funzione ha la forma scritta?', 'Non svolge alcuna funzione giuridicamente rilevante.', 'E'' un elemento essenziale per la validità del contratto.', 'Ha funzione probatoria dell''esistenza del contratto.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Tra le norme dell''assicurazione contro i danni, l''art. 1908 del codice civile relativo al valore della cosa assicurata, stabilisce che nell''accertare il danno:', 'Non può superare di un terzo il valore che la cosa stessa aveva al tempo della stipula del contratto.', 'Può essere sempre attribuito alle cose peritate o danneggiate un valore superiore a quello che avevano al tempo del sinistro.', 'Non si può attribuire alle cose perite o danneggiate un valore superiore a quello che avevano al tempo del sinistro. Il valore delle cose assicurate può essere tuttavia stabilito al tempo della conclusione del contratto, mediante stima accettata per iscritto dalle parti.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In caso di aggravamento del rischio, l''assicuratore può - ai sensi dell''art. 1898 del codice civile - recedere dal contratto. L''eventuale recesso dell''assicuratore ha:', 'sempre effetto immediato', 'sempre effetto dopo un mese se l''aggravamento del rischio è tale che per l''assicurazione sarebbe stato richiesto un premio maggiore.', 'effetto immediato se l''aggravamento è tale che l''assicuratore non avrebbe consentito l''assicurazione', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Un contratto di assicurazione stipulato con una impresa non autorizzata è:', 'Nullo, salvo ratifica dell''IVASS anche in assenza della rimozione della causa di nullità.', 'Annullabile.', 'Nullo.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Il risarcimento del danno in forma specifica:', 'Non può essere mai richiesto dal danneggiato.', 'Può essere richiesto dal danneggiato solo in caso di insolvenza del danneggiante.', 'Può essere richiesto dal danneggiato solo quando sia in tutto o in parte possibile.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Consentono di ridurre o trasferire i rischi derivanti dall’insolvenza di diritto e di fatto del debitore, le assicurazioni di cui:', 'Al ramo 18 - Assistenza.', 'Al ramo 17 - Tutela Legale.', 'Al ramo 14 - Credito.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Le polizze e le quietanze di rinnovo relative all’assicurazione obbligatoria r.c. auto, devono contenere l’indicazione della provvigione, in valore assoluto e in percentuale, riconosciuta dall’impresa all’intermediario con essa operante in rapporto diretto?', 'No, mai.', 'Si, solo in valore assoluto.', 'Si, sempre.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Si intende per "contratto unit linked”:', 'Il contratto di assicurazione in cui le prestazioni sono legate esclusivamente al verificarsi di eventi quali il decesso, l''invalidità, l''inabilità dell''assicurato.', 'Il contratto di assicurazione sulla vita in cui le prestazioni sono direttamente collegate ad un indice azionario.', 'Il contratto di assicurazione sulla vita in cui sono presenti prestazioni direttamente collegate al valore di attivi contenuti in un fondo interno detenuto dall''impresa di assicurazioni oppure al valore delle quote di OICR.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Le norme del codice civile concernenti la durata dell''assicurazione ed in particolare quelle concernenti la riduzione del premio in caso di durata poliennale, si applicano alle assicurazioni sulla vita?', 'Si.', 'Si, ma solo al ricorrere di date condizioni.', 'No.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Nell''assicurazione del ramo assistenza, la prestazione di immediato aiuto che l''impresa si impegna a fornire all''assicurato:', 'E'' solo in denaro.', 'E'' solo in natura.', 'Può essere in denaro o in natura.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Trattandosi di assicurazione r.c. auto, per i veicoli usati posti in circolazione da commercianti ai fini della vendita, per prova, collaudo o dimostrazione:', 'Le imprese di assicurazione, previa autorizzazione di IVASS, possono stipulare un''assicurazione provvisoria di durata non superiore a quindici giorni, prorogabile per più di una volta per particolari esigenze.', 'Le imprese di assicurazione possono stipulare un''assicurazione provvisoria di durata non superiore a 30 giorni, sempre prorogabile .', 'Le imprese di assicurazione hanno facoltà di stipulare un''assicurazione provvisoria di durata non superiore a cinque giorni e non prorogabile, a particolari condizioni di polizza e tariffa.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Quale tra le seguenti forme giuridiche non consente ad un''impresa di assicurazione italiana di ottenere l''autorizzazione all''esercizio dell''attività assicurativa da parte dell''IVASS?', 'Società di mutua assicurazione le cui quote di partecipazione siano rappresentate da azioni', 'Società per azioni', 'Società in accomandita semplice.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In base al Codice delle assicurazioni private, in caso di sinistro r.c.auto, chi è tenuto a risarcire il danno del terzo trasportato?', 'Il terzo trasportato può soltanto citare in giudizio l''impresa che assicura il veicolo che ha causato il danno.', 'Soltanto l''impresa di assicurazione che assicura il veicolo che ha cagionato il danno, la quale ha diritto di rivalsa nei confronti dell''impresa di assicurazione del veicolo sul quale il terzo trasportato era a bordo al momento del sinistro.', 'L''impresa di assicurazione del veicolo sul quale era a bordo il terzo trasportato al momento del sinistro, entro il massimale minimo di legge, a prescindere dall''accertamento della responsabilità dei conducenti dei veicoli coinvolti nel sinistro.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Quale soggetto è abilitato ad emettere le carte verdi per la circolazione all''estero dei veicoli a motore immatricolati in Italia?', 'Il PRA (Pubblico registro automobilitico)', 'La compagnia di assicurazione del proprietario del veicolo.', 'L''UCI (Ufficio centrale italiano)', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In caso di una polizza vita le cui prestazioni sono direttamente collegate ad indici azionari o altri valori di riferimento si è in presenza di:', 'Una polizza unit linked.', 'Un contratto di capitalizzazione.', 'Una polizza index linked.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Per poter esercitare in Italia in regime di libera prestazione di servizi l''assicurazione obbligatoria della responsabilità civile derivante dalla circolazione dei veicoli a motore e dei natanti, un''impresa comunitaria deve tra l''altro:', 'Nominare un perito in Italia per la gestione dei sinistri e per la liquidazione dei relativi risarcimenti.', 'Nominare un organo per la risoluzione delle possibili controversie e per la liquidazione dei relativi risarcimenti.', 'Nominare un rappresentante incaricato della gestione dei sinistri e della liquidazione dei relativi risarcimenti.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Secondo il codice civile, le condizioni generali di contratto predisposte da uno dei contraenti, sono efficaci nei confronti dell''altro:', 'Se la parte che le ha predisposte le ha riportate sul documento fiscale emesso in esecuzione del contratto concluso.', 'Se la parte che le ha predisposte ha maturato il convincimento che l''altro contraente, al momento della conclusione del contratto, le conoscesse.', 'Se al momento della conclusione del contratto, questi le ha conosciute o avrebbe dovuto conoscerle usando l''ordinaria diligenza.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In base all''art. 1916 c.c., l''assicuratore che abbia pagato l''indennità nell’assicurazione contro i danni è surrogato, fino alla concorrenza dell''ammontare di essa, nei diritti dell''assicurato verso i terzi responsabili?', 'No, in nessun caso', 'No, salvo patto contrario', 'Sì, salve le eccezioni previste dalla legge', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Nell''assicurazione di responsabilità civile, il termine di prescrizione del diritto all''indennizzo decorre:', 'Dal giorno in cui si è verificato il sinistro.', 'Dopo quindici giorni dalla data del sinistro, salvo nei casi di assicurazione r.c. auto.', 'Dal giorno in cui il terzo ha richiesto il risarcimento all''assicurato o ha promosso contro di lui azione per il risarcimento del danno.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'I reclami ricevuti dagli agenti in relazione al proprio comportamento, devono:', 'Essere gestiti direttamente dagli agenti.', 'Essere trasmessi con cadenza trimestrale all''IVASS.', 'Essere trasmessi senza ritardo all''impresa preponente interessata.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'La polizza Long Term Care (LTC) copre:', 'Le spese derivanti dal verificarsi di una delle gravi malattie tassativamente previste in polizza.', 'La perdita o la diminuzione definitiva e irrimediabile della capacità lavorativa derivante da invalidità permanente, se conseguente a malattia - e non a infortunio - manifestatasi successivamente alla data di efficacia del contratto, ma entro la data di scadenza dello stesso.', 'Le spese derivanti dall’impossibilità di svolgere autonomamente le funzioni della vita quotidiana con conseguente menomazione dell’autosufficienza non necessariamente dovuta a malattia o infortunio, ma anche a senescenza.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi del codice civile, la validità di un''assicurazione contratta da Tizio per il caso di morte di Caio:', 'non deve essere subordinata al consenso di Caio alla conclusione del contratto.', 'è subordinata al consenso alla conclusione del contratto provato per iscritto sia da Caio che dai suoi eredi', 'è subordinata al consenso alla conclusione del contratto fornito da Caio o dal suo legale rappresentante, provato per iscritto.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi del codice civile, l''assicuratore è obbligato a rilasciare al contraente:', 'solo i duplicati di polizza richiesti dall''assicurato con oneri per quest''ultimo', 'solo la quietanza del pagamento', 'la polizza di assicurazione o altro documento da lui sottoscritto', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi del codice civile, quale è il termine di prescrizione del diritto al pagamento delle rate di premio?', 'Due anni dalle singole scadenze.', 'Cinque anni dalle singole scadenze.', 'Un anno dalle singole scadenze.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Le somme dovute agli assicurati e agli altri aventi diritto a prestazioni assicurative si considerano effettivamente percepite dall''avente diritto soltanto:', 'Con rilascio di quietanza scritta. Non è ammessa la prova contraria dell''impresa o dell''intermediario.', 'con qualsiasi mezzo di prova anche per testimoni', 'Con rilascio di quietanza scritta, salvo prova contraria dell''impresa o dell''intermediario.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi del codice civile, se il rischio cessa di esistere dopo la conclusione del contratto di assicurazione:', 'il contratto si scioglie e l''assicuratore non ha mai diritto al pagamento del premio', 'il contratto non si scioglie e l''assicuratore ha diritto al pagamento integrale dei premi', 'il contratto si scioglie, ma l''assicuratore ha diritto al pagamento dei premi finché la cessazione del rischio non gli sia comunicata o non venga altrimenti a sua conoscenza', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi del codice civile, se la polizza di assicurazione è all''ordine o al portatore, il suo trasferimento comporta:', 'La liberazione dell''assicuratore che adempie la prestazione nei confronti del giratario o del portatore della polizza, anche in presenza di dolo o colpa grave.', 'La facoltà per l''assicuratore di scegliere se adempiere la prestazione nei confronti del girante o del giratario.', 'Il trasferimento del credito verso l''assicuratore, con gli effetti della cessione.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Trattandosi di polizze index linked, tra i profili di cui si compone il rischio di investimento, il «rischio di controparte» è quello:', 'Derivante dal rilascio al contraente da un soggetto terzo di una garanzia di adeguamento del capitale in funzione dell''andamento di un indice azionario.', 'Derivante dal rilascio al contraente da un soggetto terzo di una garanzia minima di conservazione del capitale o di interesse.', 'Derivante dalla possibilità che  l’ente  emittente  o  la controparte  non  adempia ai  propri  obblighi contrattuali.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Nell''assicurazione obbligatoria r.c. auto, in quale dei seguenti casi si applica la procedura di risarcimento diretto?', 'In caso di sinistro tra tre o più veicoli', 'In caso di sinistro dal quale siano derivati danni alla persona del conducente con conseguente invalidità permanente superiore a nove punti', 'In caso di sinistro tra due veicoli', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In base al codice civile, se un fatto dannoso è imputabile a più persone:', 'Solo il soggetto che ha maggiormente contribuito a determinare il danno è tenuto al risarcimento del danno stesso.', 'il soggetto che ha la polizza con massimale più alto.', 'Tutte sono obbligate in solido al risarcimento del danno.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Trattandosi di assicurazione obbligatoria r.c. auto, per i veicoli che circolano muniti di targa provvisoria:', 'Deve essere stipulata un''assicurazione provvisoria di durata superiore al foglio di via.', 'Deve essere stipulata un''assicurazione provvisoria di durata non superiore a tre giorni, prorogabile una sola volta per particolari esigenze.', 'L''assicurazione può essere stipulata con durata corrispondente al periodo di validità del foglio di via.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'La procedura FIN-NET:', 'Attiene i soli reclami relativi ai comportamenti degli intermediari assicurativi iscritti nella sezione D del RUI.', 'Attiene i soli reclami aventi ad oggetto i comportamenti degli intermediari assicurativi iscritti nella sezione B del RUI.', 'È attivata per la risoluzione della lite transfrontaliera di cui sia parte il reclamante avente il domicilio in Italia.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Ai sensi del Codice delle assicurazioni private, quali forme di assicurazione, tra le altre, sono espressamente vietate?', 'Quelle relative alla copertura di rischi derivanti da incidenti nucleari.', 'Quelle derivanti da eventi accidentali non specificatamente individuati nella polizza.', 'Quelle aventi per oggetto il trasferimento del rischio di pagamento delle sanzioni amministrative.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'I premi pagati dal contraente all''intermediario:', 'Possono essere versati anche in un conto personale intestato all''intermediario.', 'Devono essere trasferiti dal conto dell''intermediario su quello della compagnia per cui l''intermediario opera entro trenta giorni dalla loro riscossione.', 'Sono versati in un conto separato, del quale può essere titolare anche l''intermediario espressamente in tale qualità. Essi costituiscono un patrimonio autonomo rispetto a quello dell''intermediario medesimo.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In materia di r.c.auto, l’obbligo di indicare, in modo evidenziato, il premio di tariffa, la provvigione dell''intermediario, nonché lo sconto complessivamente riconosciuto al sottoscrittore del contratto, trova applicazione con riferimento:', 'Solo alle polizze.', 'Solo ai preventivi.', 'Sia ai preventivi che alle polizze.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In quale ramo assicurativo rientrano le polizze di capitalizzazione?', 'Nel ramo perdite pecuniarie.', 'Nel ramo cauzioni.', 'In uno dei rami vita.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Le norme del codice civile concernenti la durata dell''assicurazione ed in particolare quelle concernenti la riduzione del premio in caso di durata poliennale, si applicano alle assicurazioni sulla vita?', 'Si.', 'Si, ma solo al ricorrere di date condizioni.', 'No.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Nell''assicurazione del ramo assistenza, la prestazione di immediato aiuto che l''impresa si impegna a fornire all''assicurato:', 'E'' solo in denaro contante', 'E'' solo in natura.', 'Può essere in denaro o in natura.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Trattandosi di assicurazione r.c. auto, per i veicoli usati posti in circolazione da commercianti ai fini della vendita, per prova, collaudo o dimostrazione:', 'Le imprese di assicurazione non possono stipulare un''assicurazione provvisoria', 'Le imprese di assicurazione devono stipulare un''assicurazione a premio ridotto del 30% rispetto al premio di mercato.', 'Le imprese di assicurazione hanno facoltà di stipulare un''assicurazione provvisoria di durata non superiore a cinque giorni e non prorogabile, a particolari condizioni di polizza e tariffa.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Quale tra le seguenti forme giuridiche non consente ad un''impresa di assicurazione italiana di ottenere l''autorizzazione all''esercizio dell''attività assicurativa da parte dell''IVASS?', 'Società di mutua assicurazione le cui quote di partecipazione siano rappresentate da azioni', 'Società per azioni', 'Società a responsabilità limitata', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In caso di promozione e collocamento a distanza di contratti di assicurazione, gli intermediari e ogni altro distributore:', 'Non sono tenuti a conservare le informazioni acquisite ai fini delle valutazioni delle esigenze del cliente.', 'Sono tenuti a trasmettere ad IVASS le informazioni acquisite.', 'Adottano procedure  tali da garantire, tra l''altro, l''acquisizione da parte del contraente su supporto durevole delle informazioni richieste e di quelle fornite.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In base al Codice delle assicurazioni private, in caso di sinistro r.c.auto, chi è tenuto a risarcire il danno del terzo trasportato?', 'Il terzo trasportato può soltanto citare in giudizio l''impresa che assicura il veicolo che ha causato il danno.', 'sempre il fondo vittime della strada con domanda da proporsi entro 30 giorni dall''incidente', 'L''impresa di assicurazione del veicolo sul quale era a bordo il terzo trasportato al momento del sinistro, entro il massimale minimo di legge, a prescindere dall''accertamento della responsabilità dei conducenti dei veicoli coinvolti nel sinistro.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Quale soggetto è abilitato ad emettere le carte verdi per la circolazione all''estero dei veicoli a motore immatricolati in Italia?', 'Il PRA (Pubblico registro automobilitico)', 'Consap', 'L''UCI (Ufficio centrale italiano)', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'In caso di una polizza vita le cui prestazioni sono direttamente collegate ad indici azionari o altri valori di riferimento si è in presenza di:', 'Una polizza unit linked.', 'Una polizza parametrica', 'Una polizza index linked.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Per poter esercitare in Italia in regime di libera prestazione di servizi l''assicurazione obbligatoria della responsabilità civile derivante dalla circolazione dei veicoli a motore e dei natanti, un''impresa comunitaria deve tra l''altro:', 'Nominare un perito in Italia per la gestione dei sinistri e per la liquidazione dei relativi risarcimenti.', 'iscriversi in un''apposita albo tenuto presso Uci', 'Nominare un rappresentante incaricato della gestione dei sinistri e della liquidazione dei relativi risarcimenti.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Secondo il codice civile, le condizioni generali di contratto predisposte da uno dei contraenti, sono efficaci nei confronti dell''altro:', 'Se la parte che le ha predisposte le ha riportate sul documento fiscale emesso in esecuzione del contratto concluso.', 'Solo se questi le ha specificatamente sottoscritte', 'Se al momento della conclusione del contratto, questi le ha conosciute o avrebbe dovuto conoscerle usando l''ordinaria diligenza.', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'L''assicuratore che abbia pagato l''indennità nell’assicurazione contro i danni è surrogato, fino alla concorrenza dell''ammontare di essa, nei diritti dell''assicurato verso i terzi responsabili?', 'No, in nessun caso', 'No, salvo patto contrario', 'Sì, salve le eccezioni previste dalla legge e salvo quanto previsto nelle condizioni contrattuali', 'a'),
((SELECT id FROM materie WHERE nome = 'Diritto delle Assicurazioni inclusa la disciplina regolamentare ISVAP/IVASS' LIMIT 1), 'Nell''assicurazione di responsabilità civile, il termine di prescrizione del diritto all''indennizzo decorre:', 'Dal giorno in cui si è verificato il sinistro.', 'Dopo quindici giorni dalla data del sinistro, salvo nei casi di assicurazione r.c. auto.', 'Dal giorno in cui il terzo ha richiesto il risarcimento all''assicurato o ha promosso contro di lui azione per il risarcimento del danno e non incide sul decorso la presenza di una clausola contrattuale claims made', 'a'),
